@extends('layouts.app') @section('title','Pilih Kursi') @section('content')<div class="page"><a class="link" href="{{ route('travel.search') }}">‹ Kembali ke jadwal</a><div class="mt-7 grid gap-8 lg:grid-cols-[1fr_360px]"><div><span class="eyebrow">PILIH KURSI</span><h1 class="heading mt-2">{{ $schedule->route->origin }} → {{ $schedule->route->destination }}</h1><p class="mt-3 text-slate-600">{{ $schedule->departs_at->translatedFormat('l, d F Y · H:i') }} WIB · {{ $schedule->vehicle->model }} · {{ $schedule->vehicle->name }}</p>@guest<div class="mt-6 rounded-2xl bg-amber-50 p-5 text-amber-900">Masuk atau daftar terlebih dahulu untuk memesan. <a class="font-bold underline" href="{{ route('login') }}?redirect={{ urlencode(url()->current()) }}">Masuk sekarang</a></div>@endguest<form id="booking-form" method="post" action="{{ route('bookings.store') }}" class="mt-8">@csrf<input type="hidden" name="schedule_id" value="{{ $schedule->id }}"><div class="rounded-3xl bg-white p-6"><div class="mb-5 flex gap-5 text-sm"><span>□ Tersedia</span><span class="text-teal-700">■ Dipilih</span><span class="text-slate-400">■ Terisi</span></div><div class="mx-auto max-w-xs rounded-3xl border-2 border-slate-200 p-6"><div class="mb-5 text-right text-xs font-bold text-slate-400">DEPAN MOBIL</div><div class="grid gap-3" style="grid-template-columns:repeat({{ max(3,$schedule->vehicle->seats->max('column')) }},minmax(0,1fr))">@foreach($schedule->vehicle->seats->sortBy([['row','asc'],['column','asc']]) as $seat)@if(!$seat->selectable)<div class="seat unavailable" style="grid-row:{{ $seat->row+1 }};grid-column:{{ max(1,$seat->column) }}">Sopir</div>@else<label class="seat {{ in_array($seat->id,$occupied)?'occupied':'' }}" style="grid-row:{{ $seat->row+1 }};grid-column:{{ max(1,$seat->column) }}"><input class="seat-input" type="checkbox" value="{{ $seat->id }}" data-number="{{ $seat->number }}" @disabled(in_array($seat->id,$occupied) || !auth()->check())><span>{{ $seat->number }}</span></label>@endif @endforeach</div></div></div><div class="mt-6 rounded-3xl bg-white p-6"><h2 class="text-xl font-black">Data penumpang</h2><p class="mt-1 text-sm text-slate-500">Pilih satu kursi untuk setiap penumpang.</p><div id="passengers" class="mt-5 space-y-4"></div><div class="mt-5 grid gap-4 md:grid-cols-2"><label class="field">Nomor WhatsApp<input name="phone" required value="{{ old('phone',auth()->user()?->phone) }}"></label><label class="field">Alamat penjemputan<input name="pickup_address" required value="{{ old('pickup_address') }}"></label><label class="field">Alamat pengantaran<input name="dropoff_address" required value="{{ old('dropoff_address') }}"></label><label class="field">Catatan<input name="notes" value="{{ old('notes') }}"></label></div></div><button class="btn-primary mt-6 w-full py-4" @guest disabled @endguest>Konfirmasi Pesanan</button></form></div><aside class="h-fit rounded-3xl bg-slate-900 p-7 text-white lg:sticky lg:top-24"><span class="text-sm text-teal-300 font-bold">RINGKASAN PERJALANAN</span><h2 class="mt-4 text-2xl font-black">{{ $schedule->vehicle->model }}</h2><div class="mt-5 space-y-3 text-sm text-slate-300"><p>Rute: {{ $schedule->route->origin }} → {{ $schedule->route->destination }}</p><p>Kursi dipilih: <strong id="seat-summary" class="text-white">Belum ada</strong></p><p>Harga per kursi: Rp{{ number_format($schedule->fare,0,',','.') }}</p><p>Biaya jemput/antar mengikuti pengaturan admin.</p></div><div class="mt-7 border-t border-slate-700 pt-5 text-lg font-black">Total tiket: <span id="total">Rp0</span></div></aside></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const seats=[...document.querySelectorAll('.seat-input')],container=document.getElementById('passengers');function sync(){const selected=seats.filter(x=>x.checked);container.innerHTML=selected.map((x,i)=>`<div class="grid gap-3 rounded-xl bg-slate-50 p-4 md:grid-cols-2"><div class="md:col-span-2 text-sm font-bold">Penumpang ${i+1} · Kursi ${x.dataset.number}</div><input type="hidden" name="passengers[${i}][seat_id]" value="${x.value}"><input class="input" name="passengers[${i}][name]" placeholder="Nama lengkap" required><input class="input" name="passengers[${i}][identity_number]" placeholder="Nomor identitas (opsional)"></div>`).join('');document.getElementById('seat-summary').textContent=selected.map(x=>x.dataset.number).join(', ')||'Belum ada';document.getElementById('total').textContent='Rp'+({{ $schedule->fare }}*selected.length).toLocaleString('id-ID')}seats.forEach(x=>x.addEventListener('change',sync));document.getElementById('booking-form').addEventListener('submit',e=>{if(!seats.some(x=>x.checked)){e.preventDefault();alert('Pilih setidaknya satu kursi.')}});sync()});</script>@endsection
